part of 'user_screens.dart';

class InventoryCategoriesScreen extends StatelessWidget { const InventoryCategoriesScreen(this.state, {super.key}); final UserState state;
  @override Widget build(BuildContext context) => UserShell(state: state, title: 'Inventory', child: Column(children: [if (state.canManageInventory) Padding(padding: const EdgeInsets.fromLTRB(14, 12, 14, 0), child: ElevatedButton.icon(onPressed: () => state.go(UserPage.addProduct), icon: const Icon(Icons.add), label: const Text('Add Product'))), Expanded(child: state.categories.isEmpty ? const EmptyMessage('No active categories were returned by the server.') : GridView.builder(padding: const EdgeInsets.all(14), gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 2, mainAxisSpacing: 10, crossAxisSpacing: 10, childAspectRatio: 1.3), itemCount: state.categories.length, itemBuilder: (_, i) { final c = state.categories[i]; return UserCard(onTap: () { state.search = ''; state.go(UserPage.currentStock); }, child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [const Icon(Icons.category_rounded, color: userBlue, size: 32), const SizedBox(height: 8), Text('${c['name']}', textAlign: TextAlign.center, style: const TextStyle(fontWeight: FontWeight.w800))])); }))]));
}
